fn get_min_val(a: &Vec<i8>) -> i8 {
    // Assumes a is non-empty
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Assumes a is non-empty
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Preconditions:
    // - a.len() > 0
    // - q in [0, 100]

    // Return min if q == 0
    if q <= 0 {
        return get_min_val(&a);
    }
    // Return max if q == 100
    if q >= 100 {
        return get_max_val(&a);
    }

    // Sort the vector to find quantile positions
    a.sort_unstable();

    let n = a.len() as f64;
    let qf = q as f64 / 100.0;

    // Compute the index for the quantile: 
    // using the "nearest-rank" interpolation:
    // position = (n - 1) * qf
    // This ensures that q=0 corresponds to index 0 and q=1 corresponds to index n-1
    let pos = (n - 1.0) * qf;

    let lower_idx = pos.floor() as usize;
    let upper_idx = pos.ceil() as usize;

    if lower_idx == upper_idx {
        // pos is an integer: pick that element
        a[lower_idx]
    } else {
        // Linear interpolate between two neighbors
        let lower_val = a[lower_idx] as f64;
        let upper_val = a[upper_idx] as f64;
        let weight = pos - (lower_idx as f64);
        let interp = lower_val * (1.0 - weight) + upper_val * weight;

        // Since return type is i8, round to nearest integer within bounds
        interp.round() as i8
    }
}